export const CHOCOLATE: DialogueLine[] = [
  {"id":"p1-01","who":2,"write":null,"ms":{"kirill":2038,"alexander":2142,"zahar":2011,"ermil":2011,"filipp":2168,"dasha":2168,"lera":2142,"jane":2011,"masha":2377},"text":"Привет. Ну что, сверяемся?"},
  {"id":"p1-02","who":1,"write":null,"ms":{"kirill":1698,"alexander":1698,"ermil":1489,"filipp":1776,"zahar":1672},"text":"Давай. У тебя сколько?"},
  {"id":"p1-03","who":2,"write":null,"ms":{"kirill":6060,"alexander":5878,"ermil":5198,"zahar":5878,"filipp":6087,"dasha":5904,"lera":6034,"masha":6296,"jane":5564},"text":"Пять. Стороны, диагонали, угол. А у тебя? Ты чего написал, как курица лапкой?"},
  {"id":"p1-04","who":1,"write":null,"ms":{"kirill":5512,"alexander":5172,"ermil":5198,"zahar":5224,"filipp":5851},"text":"Да я без планшета сегодня. Мы к тёте в гости приехали, с её компа мышкой рисую."},
  {"id":"p1-05","who":2,"write":null,"ms":{"kirill":2142,"filipp":2220,"zahar":2168,"alexander":2038,"ermil":1985,"lera":2220,"dasha":2142,"masha":2247,"jane":2064},"text":"Понятно. Ладно, разберу."},
  {"id":"p1-06","who":2,"write":null,"ms":{"kirill":9561,"alexander":9300,"ermil":9221,"dasha":9352,"lera":9587,"masha":9874,"filipp":9613,"zahar":9326,"jane":9012},"text":"Так. А-дэ равно бэ-цэ, есть. А-бэ равно цэ-дэ, есть. Углы, правильно… А это что? А-бэ равно а-о?"},
  {"id":"p1-07","who":1,"write":null,"ms":{"kirill":3004,"alexander":2978,"ermil":2743,"filipp":3056,"zahar":3030},"text":"Ну да. Посмотри на чертёж, — одинаковые."},
  {"id":"p1-08","who":2,"write":null,"ms":{"kirill":3187,"alexander":2978,"zahar":3082,"ermil":3109,"filipp":3213,"dasha":3082,"lera":3213,"masha":3239,"jane":3265},"text":"Похожи, конечно. Но мне кажется, что они не равны."},
  {"id":"p1-09","who":1,"write":null,"ms":{"kirill":3291,"alexander":3213,"ermil":3109,"zahar":3239,"filipp":3239},"text":"Почему не равны? Палец приложи, — одинаковые."},
  {"id":"p1-10","who":2,"write":null,"ms":{"kirill":10501,"alexander":9718,"ermil":9691,"zahar":10031,"filipp":10031,"dasha":9796,"lera":10240,"masha":10240,"jane":10005},"text":"Да как я его тут приложу? Я ещё вот по клеткам смотрю. А-бэ — это два вправо, четыре вверх. А-о, — пять вправо, два вверх. Разные."},
  {"id":"p1-11","who":1,"write":null,"ms":{"kirill":9848,"alexander":9012,"ermil":9273,"filipp":9691,"zahar":9195},"text":"Как ты так сравниваешь? У тебя и вправо, и вверх разное количество каждый раз. А длина может быть одна и та же. Наискосок ведь."},
  {"id":"p1-12","who":2,"write":null,"ms":{"kirill":3997,"zahar":3918,"alexander":3866,"ermil":3840,"dasha":3762,"filipp":4075,"lera":3944,"masha":3997,"jane":3840},"text":"Нет. Так не бывает. Да и видно, что разные немного."},
  {"id":"p1-13","who":1,"write":null,"ms":{"kirill":1724,"zahar":1620,"alexander":1593,"ermil":1620,"filipp":1829},"text":"А мне видно, что одинаковые."},
  {"id":"p1-14","who":2,"write":null,"ms":{"kirill":1358,"alexander":1411,"zahar":1332,"ermil":1358,"filipp":1463,"dasha":1332,"lera":1437,"masha":1384,"jane":1358},"text":"Ну и как мы узнаем?"},
  {"id":"p1-15","who":1,"write":null,"ms":{"kirill":2299,"alexander":2220,"ermil":2168,"zahar":2220,"filipp":2351},"text":"Не знаю. Давай учителя позовём."},
  {"id":"p1-16","who":2,"write":null,"ms":{"kirill":653,"zahar":653,"alexander":627,"ermil":575,"filipp":679,"dasha":653,"lera":653,"masha":627,"jane":627},"text":"Давай."},
  {"id":"p1-17","who":2,"write":null,"ms":{"kirill":10083,"alexander":9326,"ermil":9796,"zahar":9169,"dasha":9378,"filipp":10083,"lera":9639,"masha":10266,"jane":9430},"text":"Мы сверяемся. У Миши записано, что а-бэ равно а-о, а я думаю, что не равны, раз по клеткам вправо и вверх не совпадают. Как правильно?"},
  {"id":"p1-18","who":2,"write":null,"ms":{"kirill":3553,"alexander":3422,"ermil":3370,"zahar":3553,"filipp":3762,"dasha":3527,"lera":3527,"masha":3788,"jane":3448},"text":"Два в квадрате плюс четыре в квадрате… двадцать."},
  {"id":"p1-19","who":1,"write":null,"ms":{"kirill":8908,"alexander":8359,"ermil":7993,"zahar":8568,"filipp":8620},"text":"А пять в квадрате плюс два в квадрате — двадцать девять. Да, точно, не равны. Ладно, теперь понятно. Вычёркиваю."},
  {"id":"p1-20","who":2,"write":null,"ms":{"kirill":1776,"alexander":1672,"ermil":1593,"zahar":1593,"filipp":1776,"dasha":1855,"lera":1829,"jane":1750,"masha":1881},"text":"Видишь? Я же говорил."},
  {"id":"p1-21","who":1,"write":null,"ms":{"kirill":9509,"alexander":8673,"ermil":9064,"zahar":8934,"filipp":9509},"text":"Ты говорил, что вправо-вверх не совпадает, значит, не равны. А бывает, что не совпадает, а длина одна. Просто тут не совпало."},
  {"id":"p1-21f","who":1,"write":null,"ms":{"kirill":9535,"alexander":8725,"ermil":9117,"zahar":8908,"filipp":9561},"text":"Ты говорила, что вправо-вверх не совпадает, значит, не равны. А бывает, что не совпадает, а длина одна. Просто тут не совпало."},
  {"id":"p1-22","who":2,"write":null,"ms":{"kirill":4258,"zahar":4180,"alexander":3997,"ermil":3892,"filipp":4232,"lera":4153,"dasha":3997,"masha":4232,"jane":3918},"text":"Ну… да. По одним клеткам не скажешь. Посчитать надо."},
  {"id":"p1-23","who":1,"write":null,"ms":{"kirill":5721,"alexander":5381,"ermil":5355,"zahar":5486,"filipp":5851},"text":"Давай теперь общий список. По очереди. Кто сказал, тот и пишет. Начинай."},
  {"id":"p1-24","who":2,"write":"AD = BC","ms":{"kirill":1306,"alexander":1332,"ermil":1358,"zahar":1306,"filipp":1384,"dasha":1306,"lera":1358,"masha":1384,"jane":1332},"text":"А-дэ равно бэ-цэ."},
  {"id":"p1-25","who":1,"write":"AB = CD","ms":{"kirill":1254,"alexander":1202,"ermil":1306,"filipp":1358,"zahar":1280},"text":"А-бэ равно цэ-дэ."},
  {"id":"p1-26","who":2,"write":"AO = OC","ms":{"kirill":4780,"alexander":4441,"ermil":4415,"dasha":4310,"lera":4571,"zahar":4389,"filipp":4519,"masha":4545,"jane":4180},"text":"А-о, равно о-цэ. Пять и два, пять и два, — тут не поспоришь."},
  {"id":"p1-27","who":1,"write":"BO = OD","ms":{"kirill":5146,"alexander":4571,"ermil":4650,"zahar":4807,"filipp":4859},"text":"Бэ-о равно о-дэ. Три и два, три и два. Этого у меня не было."},
  {"id":"p1-28","who":2,"write":"∠A = ∠C","ms":{"kirill":2142,"zahar":2011,"alexander":1985,"ermil":1985,"filipp":2064,"dasha":1959,"lera":2142,"masha":2011,"jane":1881},"text":"Угол. А. равен углу цэ."},
  {"id":"p1-29","who":1,"write":"∠B = ∠D","ms":{"kirill":3866,"alexander":3474,"ermil":3709,"zahar":3788,"filipp":3736},"text":"И угол бэ равен углу дэ. А этого не было у тебя."},
  {"id":"p1-30","who":2,"write":null,"ms":{"kirill":1698,"alexander":1593,"zahar":1541,"ermil":1515,"filipp":1698,"dasha":1620,"lera":1724,"masha":1802,"jane":1567},"text":"Всё равно шесть получилось."},
  {"id":"p1-31","who":1,"write":null,"ms":{"kirill":1567,"alexander":1567,"zahar":1541,"ermil":1489,"filipp":1750},"text":"Только теперь все честные."},
  {"id":"p1-32","who":1,"write":null,"ms":{"kirill":2351,"alexander":2247,"ermil":2194,"zahar":2429,"filipp":2456},"text":"Ой! Здравствуйте, Татьяна Алексеевна."},
  {"id":"p1-33","who":1,"write":null,"ms":{"kirill":8411,"alexander":7784,"ermil":7628,"zahar":7784,"filipp":8594},"text":"Татьяна Алексеевна, у меня записано, что а-бэ равно а о. На глаз одинаковые, а по клеткам разные. Как правильно?"},
  {"id":"p1-tq","who":"T","write":null,"ms":{"alena":2351,"anton":2273},"text":"Какой у вас вопрос?"},
  {"id":"p1-ta","who":"T","write":null,"ms":{"alena":20193,"anton":19879},"text":"Мы не можем утверждать, что отрезки равны, потому что так кажется из чертежа. Но то, что количество клеток вправо и вверх не совпадает, тоже не доказательство, что а-бэ не равно а-о. Тут Миша прав. Вспомните теорему Пифагора: клетки, — это катеты, а ваши отрезки, — гипотенузы. Посчитайте."},
];
