/** П2 «Давай я быстро объясню»: the strong one (1) explains, the other (2) gets it; T is the teacher coming in openly.
 *  p2-01…p2-36 in order, p2-25f «сама» for a girl; on a visit p2-tq, 37, 38, p2-tb, 39. Every line in all eight voices.
 *  Text: ~/temp/П2-объясню.txt */
export const EXPLAIN: DialogueLine[] = [
  {"id":"p2-01","who":1,"write":null,"ms":{"filipp":1567,"zahar":1567,"kirill":1567,"alexander":1593,"ermil":1384,"dasha":1646,"lera":1620,"masha":1724,"jane":1332},"text":"Ну что, сверяемся?"},
  {"id":"p2-02","who":2,"write":null,"ms":{"kirill":4807,"zahar":4415,"filipp":4989,"alexander":4493,"ermil":4519,"dasha":4676,"lera":4807,"masha":4963,"jane":4545},"text":"Давай. Только сразу скажу я вообще не очень понял как тут равное искать."},
  {"id":"p2-03","who":2,"write":null,"ms":{"kirill":6583,"zahar":6452,"filipp":7053,"alexander":6322,"ermil":6269,"dasha":6322,"lera":6478,"masha":6687,"jane":6504},"text":"Одну пару сторон нашёл и всё. Остальные наискосок идут. Вроде похожи а может и нет."},
  {"id":"p2-04","who":2,"write":null,"ms":{"kirill":2795,"zahar":2664,"filipp":3004,"alexander":2769,"ermil":2664,"dasha":2691,"lera":2873,"masha":2873,"jane":2743},"text":"А как равные углы искать совсем не понимаю."},
  {"id":"p2-05","who":1,"write":null,"ms":{"kirill":3683,"zahar":3448,"filipp":3814,"alexander":3370,"dasha":3605,"ermil":3657,"lera":3553,"masha":3579,"jane":3187},"text":"Да, вижу. А-дэ равно бэ-цэ. Это правильно."},
  {"id":"p2-06","who":2,"write":null,"ms":{"kirill":2090,"zahar":2064,"filipp":2194,"ermil":2011,"alexander":2168,"dasha":2038,"lera":2247,"masha":2142,"jane":2011},"text":"Ого! А у тебя сколько всего."},
  {"id":"p2-07","who":1,"write":null,"ms":{"kirill":6687,"zahar":6060,"filipp":6766,"alexander":6165,"ermil":6113,"dasha":6374,"lera":6400,"masha":6844,"jane":6374},"text":"Да тут не очень сложно давай быстро объясню. Нам ведь обоим нужно понимать. Спросить могут любого."},
  {"id":"p2-08","who":2,"write":null,"ms":{"kirill":1933,"zahar":1776,"filipp":1959,"alexander":1829,"ermil":1620,"lera":1907,"dasha":1881,"masha":1881,"jane":1724},"text":"Давай. Только не быстро."},
  {"id":"p2-09","who":1,"write":null,"ms":{"kirill":4284,"zahar":3971,"filipp":4336,"alexander":4153,"ermil":3814,"dasha":4415,"lera":4258,"masha":4362,"jane":3370},"text":"Хорошо, не быстро. Смотри. ты помнишь теорему Пифагора?"},
  {"id":"p2-10","who":2,"write":null,"ms":{"kirill":4545,"zahar":4467,"filipp":4754,"alexander":4493,"ermil":4336,"dasha":4519,"lera":4702,"masha":4911,"jane":4441},"text":"Ну так, не очень. Там как-то стороны треугольника между собой связаны."},
  {"id":"p2-11","who":1,"write":null,"ms":{"kirill":6583,"zahar":6348,"filipp":6740,"alexander":6217,"ermil":6165,"dasha":6713,"lera":6740,"masha":6949,"jane":6217},"text":"Да, прямоугольного… Есть! Придумал проще! Помнишь первый признак равенства треугольников?"},
  {"id":"p2-12","who":2,"write":null,"ms":{"kirill":3265,"zahar":3187,"filipp":3344,"alexander":3109,"ermil":3082,"dasha":3161,"lera":3265,"masha":3396,"jane":3187},"text":"Конечно. По двум сторонам и углу между ними."},
  {"id":"p2-13","who":1,"write":null,"ms":{"kirill":8699,"zahar":8020,"filipp":9038,"alexander":8072,"ermil":8255,"dasha":7993,"lera":8098,"masha":8673,"jane":8359},"text":"Он самый. Теперь смотри на а-бэ и цэ-дэ. Давай вот такой треугольник построим к а-бэ и вот такой к цэ-дэ."},
  {"id":"p2-14","who":2,"write":null,"ms":{"kirill":1280,"zahar":1228,"filipp":1254,"alexander":1254,"ermil":1123,"dasha":1228,"lera":1306,"masha":1280,"jane":1123},"text":"Ага, вижу."},
  {"id":"p2-15","who":1,"write":null,"ms":{"kirill":3448,"zahar":3187,"filipp":3474,"alexander":3187,"ermil":3265,"dasha":3265,"lera":3370,"masha":3579,"jane":3213},"text":"Вот эти стороны у них по четыре клетки а эти по две."},
  {"id":"p2-16","who":2,"write":null,"ms":{"kirill":575,"zahar":549,"filipp":549,"alexander":522,"ermil":470,"dasha":522,"lera":522,"masha":496,"jane":496},"text":"Да."},
  {"id":"p2-17","who":1,"write":null,"ms":{"kirill":4702,"zahar":4362,"filipp":4989,"alexander":4206,"ermil":4545,"dasha":4467,"lera":4598,"masha":4676,"jane":4989},"text":"А вот эти углы прямые по девяносто градусов. Значит равны между собой."},
  {"id":"p2-18","who":2,"write":null,"ms":{"kirill":967,"zahar":967,"filipp":1019,"alexander":967,"ermil":888,"dasha":914,"lera":1071,"masha":993,"jane":914},"text":"Есть такое."},
  {"id":"p2-19","who":1,"write":null,"ms":{"kirill":7967,"zahar":7419,"filipp":7941,"alexander":7340,"dasha":7393,"ermil":7314,"masha":7915,"lera":7732,"jane":7628},"text":"Ну и всё. Значит треугольники равны и оставшиеся стороны у них тоже равны. То есть а-бэ равно цэ-дэ."},
  {"id":"p2-20","who":2,"write":null,"ms":{"kirill":2952,"zahar":2873,"filipp":2978,"alexander":2821,"ermil":2717,"dasha":2873,"lera":3135,"masha":3056,"jane":2795},"text":"Ага, точно! Так просто оказывается!"},
  {"id":"p2-21","who":1,"write":null,"ms":{"kirill":7340,"zahar":6896,"filipp":7367,"alexander":6975,"ermil":6661,"dasha":6949,"lera":7053,"masha":7471,"jane":6870},"text":"Да. А теперь такие же треугольники можно дорисовать к диагонали а-цэ. Вот один а вот второй."},
  {"id":"p2-22","who":2,"write":null,"ms":{"kirill":470,"zahar":496,"filipp":496,"alexander":444,"ermil":444,"dasha":470,"lera":470,"masha":470,"jane":470},"text":"Так."},
  {"id":"p2-23","who":1,"write":null,"ms":{"kirill":4310,"zahar":4362,"filipp":4415,"alexander":4232,"ermil":4180,"dasha":4127,"lera":4415,"masha":4467,"jane":4153},"text":"И то же самое. Получаем что а-о равно о-цэ."},
  {"id":"p2-24","who":2,"write":null,"ms":{"kirill":5355,"zahar":5068,"filipp":5381,"alexander":4937,"ermil":4937,"dasha":4963,"lera":5172,"masha":5460,"jane":4989},"text":"Гениально! Кажется я уловил идею. Так ведь и про вторую диагональ можно."},
  {"id":"p2-25","who":1,"write":null,"ms":{"kirill":2560,"zahar":2534,"filipp":2560,"alexander":2482,"ermil":2429,"dasha":2560,"lera":2586,"masha":2586,"jane":2377},"text":"Да, то же самое. Попробуй сам."},
  {"id":"p2-25f","who":1,"write":null,"ms":{"kirill":2638,"zahar":2534,"filipp":2560,"alexander":2508,"ermil":2482,"dasha":2560,"lera":2664,"masha":2691,"jane":2429},"text":"Да, то же самое. Попробуй сама."},
  {"id":"p2-26","who":2,"write":null,"ms":{"kirill":8202,"zahar":7471,"filipp":8124,"alexander":7497,"ermil":7288,"dasha":7549,"lera":7889,"masha":8150,"jane":7732},"text":"Так… дорисовываю треугольники. Эти стороны равны эти равны угол прямой. Значит бэ-о равно о-дэ."},
  {"id":"p2-27","who":1,"write":null,"ms":{"zahar":3840,"kirill":4127,"filipp":4049,"alexander":3944,"ermil":3997,"dasha":3918,"lera":4127,"masha":4180,"jane":3944},"text":"Да, всё правильно. Таким же образом можно и про углы."},
  {"id":"p2-28","who":2,"write":null,"ms":{"kirill":967,"zahar":1045,"filipp":1071,"alexander":1071,"dasha":1045,"ermil":967,"lera":1097,"masha":1123,"jane":993},"text":"Это про какие?"},
  {"id":"p2-29","who":1,"write":null,"ms":{"kirill":5642,"zahar":5381,"filipp":5538,"alexander":5277,"ermil":5016,"dasha":5381,"lera":5564,"masha":5721,"jane":4989},"text":"Про противоположные. Что угол а равен углу цэ. Видишь, одинаковые?"},
  {"id":"p2-30","who":2,"write":null,"ms":{"kirill":4415,"zahar":4284,"filipp":4467,"alexander":4180,"ermil":4206,"dasha":4232,"lera":4362,"masha":4493,"jane":4284},"text":"Да, похожи. Нет… не соображу какие треугольники взять."},
  {"id":"p2-31","who":1,"write":null,"ms":{"kirill":4780,"zahar":4598,"filipp":4833,"alexander":4467,"ermil":4415,"dasha":4598,"lera":4519,"masha":4911,"jane":4519},"text":"Смотри. Давай проведём эту высоту из бэ и эту из дэ."},
  {"id":"p2-32","who":2,"write":null,"ms":{"kirill":627,"zahar":653,"filipp":653,"alexander":653,"ermil":601,"dasha":601,"lera":679,"masha":627,"jane":627},"text":"Вижу."},
  {"id":"p2-33","who":1,"write":null,"ms":{"kirill":2664,"zahar":2638,"filipp":2743,"alexander":2560,"ermil":2534,"dasha":2560,"lera":2612,"masha":2743,"jane":2612},"text":"Теперь вот этот и вот этот треугольники."},
  {"id":"p2-34","who":2,"write":null,"ms":{"kirill":6191,"filipp":6217,"zahar":5956,"alexander":5695,"ermil":5773,"lera":6087,"dasha":5956,"masha":6139,"jane":5904},"text":"Точно! Снова две стороны и угол между ними. Значит угол. А. равен углу цэ."},
  {"id":"p2-35","who":1,"write":null,"ms":{"kirill":5799,"zahar":5329,"filipp":5590,"alexander":5277,"ermil":5016,"dasha":5381,"lera":5642,"masha":5851,"jane":5251},"text":"Да. Когда по клеткам считаешь, это самый простой способ пристраивать такие треугольники."},
  {"id":"p2-36","who":2,"write":null,"ms":{"kirill":2900,"zahar":2847,"filipp":3135,"alexander":2900,"ermil":2795,"dasha":2952,"lera":3109,"masha":3213,"jane":2821},"text":"Спасибо классный способ! Теперь всё понятно."},
  {"id":"p2-37","who":2,"write":null,"ms":{"kirill":7497,"zahar":7053,"filipp":7889,"alexander":6975,"ermil":7053,"dasha":7236,"lera":7497,"masha":7889,"jane":7602},"text":"Здравствуйте Татьяна Алексеевна. Мне сначала вообще было непонятно. А сейчас объясняют и вроде ясно становится."},
  {"id":"p2-38","who":1,"write":null,"ms":{"kirill":3944,"zahar":3762,"filipp":4258,"alexander":3683,"ermil":3840,"dasha":3814,"lera":3762,"masha":4075,"jane":3944},"text":"Достраиваем треугольники по клеткам и смотрим первый признак."},
  {"id":"p2-39","who":2,"write":null,"ms":{"kirill":2064,"zahar":2011,"filipp":2116,"alexander":2064,"ermil":1985,"dasha":2038,"lera":2142,"masha":2168,"jane":1881},"text":"Так. На чём мы остановились?"},
  {"id":"p2-tq","who":"T","write":null,"ms":{"alena":1567,"anton":1515},"text":"Как вы тут? Как дела?"},
  {"id":"p2-tb","who":"T","write":null,"ms":{"alena":2795,"anton":2691},"text":"Отлично. Разбирайтесь, не буду мешать."},
];
