/** П3 «Хоть ножницы нарисуй»: vertical angles, a bet, a draw. Text: ~/temp/П3-ножницы.txt (voice-tools/gen_p3.py) */
export const SCISSORS: DialogueLine[] = [
  {"id":"p3-01","who":1,"write":null,"ms":{"kirill":2900,"zahar":2926,"alexander":2664,"filipp":3004,"dasha":2978,"ermil":2795,"masha":3265,"lera":3004,"jane":2586},"text":"Ну что, сверяемся? У тебя что есть?"},
  {"id":"p3-02","who":2,"write":null,"ms":{"kirill":2978,"zahar":3056,"filipp":3082,"alexander":2873,"ermil":2926,"dasha":2978,"lera":3004,"masha":3213,"jane":3135},"text":"Стороны и диагонали. Четыре равенства."},
  {"id":"p3-03","who":1,"write":null,"ms":{"kirill":4284,"zahar":3866,"ermil":4153,"filipp":4676,"alexander":3971,"dasha":3971,"lera":4049,"jane":3840,"masha":4180},"text":"Ага, вижу. Я тоже их нашёл и ещё две пары углов."},
  {"id":"p3-04","who":2,"write":"AD = BC|AB = CD","ms":{"kirill":4545,"alexander":4362,"zahar":4519,"filipp":4598,"ermil":4336,"dasha":4336,"lera":4467,"masha":4676,"jane":4389},"text":"О! интересно. Давай, я стороны выписываю, а ты диагонали."},
  {"id":"p3-05","who":1,"write":"AO = OC|BO = OD","ms":{"zahar":2534,"kirill":2873,"filipp":2769,"alexander":2560,"ermil":2664,"dasha":2377,"lera":2717,"masha":2691,"jane":2456},"text":"А о равно о-цэ, бэ-о равно о-дэ."},
  {"id":"p3-06","who":2,"write":null,"ms":{"zahar":6217,"kirill":6034,"filipp":6296,"alexander":5878,"ermil":5590,"dasha":5799,"lera":6165,"masha":6374,"jane":5982},"text":"А это что такое? Угол ао бэ равен углу цэо дэ. Это не считается."},
  {"id":"p3-07","who":1,"write":null,"ms":{"kirill":601,"zahar":679,"filipp":653,"alexander":653,"ermil":601,"dasha":653,"lera":679,"masha":653,"jane":627},"text":"Почему?"},
  {"id":"p3-08","who":2,"write":null,"ms":{"kirill":4963,"zahar":4728,"alexander":4650,"filipp":5251,"ermil":4885,"dasha":4728,"lera":4989,"masha":5042,"jane":4963},"text":"Это вертикальные. Они всегда равны, в любой фигуре. Хоть ножницы нарисуй."},
  {"id":"p3-09","who":1,"write":null,"ms":{"kirill":3840,"zahar":3683,"filipp":3762,"alexander":3683,"ermil":3631,"dasha":3709,"lera":3788,"masha":3892,"jane":3814},"text":"Ну и что? Задание — записать, что равно. Они равны."},
  {"id":"p3-10","who":2,"write":null,"ms":{"kirill":5538,"zahar":5460,"filipp":5930,"alexander":5198,"ermil":5198,"dasha":5329,"lera":5564,"masha":5878,"jane":5381},"text":"Тогда ещё давай запишем, что ао цэ равно бэо дэ. По сто восемьдесят градусов."},
  {"id":"p3-11","who":1,"write":null,"ms":{"kirill":914,"zahar":993,"filipp":967,"alexander":914,"ermil":888,"dasha":914,"lera":1019,"masha":940,"jane":940},"text":"Это другое."},
  {"id":"p3-12","who":2,"write":null,"ms":{"kirill":914,"zahar":888,"filipp":940,"alexander":914,"ermil":810,"lera":967,"dasha":862,"masha":940,"jane":888},"text":"Чем другое?"},
  {"id":"p3-13","who":1,"write":null,"ms":{"kirill":6008,"zahar":5982,"filipp":6348,"alexander":5695,"dasha":5930,"ermil":6008,"lera":6269,"masha":6504,"jane":6060},"text":"Тем, что… ну это просто прямые, там вообще ничего не нужно. А здесь диагоналями образуются."},
  {"id":"p3-14","who":2,"write":null,"ms":{"kirill":1698,"zahar":1620,"filipp":1724,"alexander":1646,"ermil":1567,"dasha":1646,"lera":1698,"masha":1776,"jane":1593},"text":"Так они у всех образуются."},
  {"id":"p3-15","who":1,"write":null,"ms":{"kirill":1959,"zahar":1959,"filipp":2247,"alexander":1933,"ermil":1959,"dasha":2064,"lera":2142,"jane":1855,"masha":2299},"text":"Слушай, ты всегда так споришь?"},
  {"id":"p3-16","who":2,"write":null,"ms":{"kirill":1176,"zahar":1202,"filipp":1280,"alexander":1149,"ermil":1202,"dasha":1176,"lera":1254,"masha":1280,"jane":1228},"text":"Только когда прав."},
  {"id":"p3-17","who":1,"write":null,"ms":{"kirill":1933,"zahar":1959,"filipp":2038,"alexander":1933,"ermil":1985,"dasha":2090,"lera":2064,"masha":2064,"jane":1802},"text":"А вот и не прав. Спорим?"},
  {"id":"p3-17f","who":1,"write":null,"ms":{"kirill":2064,"zahar":2090,"filipp":2090,"alexander":2064,"ermil":1933,"dasha":2116,"lera":2142,"masha":2090,"jane":1855},"text":"А вот и не права. Спорим?"},
  {"id":"p3-18","who":2,"write":null,"ms":{"zahar":1881,"kirill":1802,"filipp":1855,"alexander":1724,"ermil":1698,"dasha":1855,"lera":1907,"jane":1802,"masha":1907},"text":"Спорим! На шоколадку!"},
  {"id":"p3-19","who":1,"write":null,"ms":{"kirill":1907,"zahar":1907,"filipp":1959,"ermil":1802,"alexander":1881,"dasha":1933,"jane":1933,"masha":2011,"lera":1959},"text":"Идёт. А кто прав-то?"},
  {"id":"p3-20","who":2,"write":null,"ms":{"kirill":993,"zahar":1045,"alexander":940,"filipp":1097,"ermil":888,"dasha":967,"lera":1019,"masha":1019,"jane":914},"text":"Давай позовём."},
  {"id":"p3-21","who":1,"write":null,"ms":{"kirill":7314,"zahar":6609,"filipp":7367,"alexander":6635,"ermil":6766,"dasha":6740,"lera":7105,"masha":7314,"jane":7053},"text":"Мы спорим, можно ли записать, что угол а-о-бэ равен углу цэ-о-дэ. Я думаю, можно, они же равны."},
  {"id":"p3-22","who":2,"write":null,"ms":{"kirill":6008,"zahar":5721,"filipp":6400,"alexander":5538,"ermil":5904,"dasha":5669,"lera":5878,"masha":6243,"jane":5878},"text":"А я думаю, что это вертикальные углы, и к параллелограмму они отношения не имеют. Кто прав?","gap":2500},
  {"id":"p3-23","who":1,"write":null,"ms":{"kirill":1593,"zahar":1646,"filipp":1593,"alexander":1541,"ermil":1437,"dasha":1593,"lera":1646,"jane":1515,"masha":1593},"text":"Оба правы. Это как?"},
  {"id":"p3-24","who":2,"write":null,"ms":{"kirill":1045,"zahar":1045,"filipp":1176,"alexander":1071,"ermil":967,"dasha":1071,"lera":1123,"masha":1019,"jane":1019},"text":"Ничья, значит."},
  {"id":"p3-25","who":1,"write":null,"ms":{"kirill":1672,"zahar":1620,"filipp":1724,"alexander":1593,"ermil":1567,"dasha":1593,"lera":1646,"masha":1698,"jane":1646},"text":"Тогда шоколадку пополам."},
  {"id":"p3-26","who":2,"write":null,"ms":{"kirill":1541,"zahar":1593,"filipp":1724,"alexander":1489,"ermil":1463,"dasha":1541,"lera":1672,"masha":1672,"jane":1567},"text":"Каждый себе по половинке."},
  {"id":"p3-27","who":1,"write":"∠AOB = ∠COD *|∠BOC = ∠AOD *","ms":{"kirill":8829,"zahar":8020,"filipp":8829,"alexander":7837,"ermil":7732,"dasha":8333,"lera":8516,"masha":8829,"jane":8124},"text":"Ладно. Давай оставим, но со звёздочкой. Если в четвёрке будем обсуждать, зададим ребятам этот вопрос. Пускай тоже подумают."},
  {"id":"p3-28","who":2,"write":null,"ms":{"kirill":1750,"zahar":1672,"filipp":1724,"alexander":1698,"ermil":1620,"dasha":1776,"lera":1829,"masha":1802,"jane":1724},"text":"Ага, пусть помучаются."},
  {"id":"p3-29","who":1,"write":null,"ms":{"kirill":2534,"zahar":2403,"filipp":2586,"alexander":2429,"ermil":2273,"dasha":2534,"lera":2586,"masha":2743,"jane":2534},"text":"Сколько мы всего насобирали, получается?"},
  {"id":"p3-30","who":2,"write":null,"ms":{"kirill":3187,"zahar":3004,"filipp":3370,"alexander":3082,"ermil":3109,"dasha":3004,"lera":3213,"masha":3318,"jane":3109},"text":"Четыре по отрезкам и два про углы со звёздочкой."},
  {"id":"p3-31","who":1,"write":null,"ms":{"kirill":3448,"filipp":3683,"zahar":3082,"alexander":3239,"ermil":3448,"dasha":3318,"lera":3396,"masha":3553,"jane":3161},"text":"А интересно, про какие углы тогда в задании написано?"},
  {"id":"p3-32","who":2,"write":null,"ms":{"kirill":3396,"zahar":3318,"filipp":3553,"alexander":3213,"ermil":3291,"dasha":3396,"lera":3474,"masha":3579,"jane":3004},"text":"Надо подумать. Просто углы параллелограмма, может быть?"},
  {"id":"p3-33","who":1,"write":null,"ms":{"kirill":3161,"zahar":3239,"filipp":3291,"alexander":3135,"ermil":3135,"dasha":3030,"lera":3187,"masha":3187,"jane":3082},"text":"А и бэ точно не равны, а вот а и цэ..."},
  {"id":"p3-34","who":2,"write":null,"ms":{"kirill":1071,"zahar":1071,"filipp":1176,"ermil":967,"alexander":1045,"dasha":1045,"lera":1097,"jane":1045,"masha":1097},"text":"По-моему, равны."},
  {"id":"p3-35","who":1,"write":"∠A = ∠C","ms":{"kirill":5251,"zahar":5277,"filipp":5564,"alexander":4963,"ermil":5094,"dasha":5146,"lera":5407,"masha":5538,"jane":5224},"text":"По-моему, тоже. Не знаю почему, но давай запишем. Нам же только найти нужно."},
  {"id":"p3-36","who":2,"write":"∠B = ∠D","ms":{"kirill":3866,"zahar":3657,"filipp":3944,"alexander":3605,"ermil":3814,"dasha":3579,"lera":3840,"masha":3918,"jane":3683},"text":"Согласен. И, кажется, ещё угол бэ равен углу дэ."},
  {"id":"p3-37","who":1,"write":null,"ms":{"kirill":2952,"zahar":2691,"filipp":2847,"ermil":2664,"alexander":2612,"dasha":2900,"lera":2900,"jane":2534,"masha":2821},"text":"Да, давай, выглядят очень похожими."},
  {"id":"p3-41","who":2,"write":null,"ms":{"kirill":4728,"zahar":4859,"filipp":4833,"ermil":4624,"alexander":4754,"dasha":4754,"lera":4859,"jane":4728,"masha":4911},"text":"Хорошо, тогда записываю. Готово."},
  {"id":"p3-38","who":1,"write":null,"ms":{"zahar":2456,"kirill":2429,"filipp":2586,"alexander":2273,"ermil":2247,"dasha":2325,"masha":2612,"lera":2456,"jane":2377},"text":"Ой, здравствуйте, Татьяна Алексеевна."},
  {"id":"p3-39","who":1,"write":null,"ms":{"kirill":6844,"filipp":6975,"zahar":6609,"alexander":6583,"ermil":6217,"dasha":6583,"lera":6792,"masha":7210,"jane":6687},"text":"Идёт. Давай спросим. Татьяна Алексеевна, можно записать, что угол ао-бэ равен углу цэо-дэ?"},
  {"id":"p3-40","who":2,"write":null,"ms":{"kirill":5669,"zahar":5251,"filipp":5825,"alexander":5094,"ermil":5303,"dasha":5355,"lera":5460,"masha":5747,"jane":5251},"text":"А я говорю, это вертикальные, они у любых двух прямых равны. Это не про параллелограмм.","gap":2500},
  {"id":"p3-tq","who":"T","write":null,"ms":{"alena":2351,"anton":2273},"text":"Какой у вас вопрос?"},
  {"id":"p3-ta","who":"T","write":null,"ms":{"alena":15256,"anton":14942},"text":"Вертикальные углы действительно равны, тут не поспоришь. Но диагонали любого четырёхугольника, пересекаясь, дают равные вертикальные углы. А в этом задании мы ищем то, что характерно именно для параллелограмма. Так что вы оба правы.","gap":2100},
];
